import React from 'react';

const SPECIALTY_ICONS = {
  Cardiologist: '❤️',
  Dentist: '🦷',
  Dermatologist: '🧴',
  Neurologist: '🧠',
  Pediatrician: '👶',
  'Orthopedic Surgeon': '🦴',
  Psychiatrist: '🧘',
};

export default function DoctorCard({ doctor, selectedDate, selectedTime, onBook, onChat }) {
  const icon = SPECIALTY_ICONS[doctor.specialization] || '👨‍⚕️';

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 flex flex-col gap-4 hover:shadow-md transition-shadow duration-200">
      {/* Header */}
      <div className="flex items-start gap-4">
        <div className="w-14 h-14 rounded-full bg-blue-50 flex items-center justify-center text-2xl flex-shrink-0">
          {icon}
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="font-semibold text-gray-900 text-base truncate">{doctor.name}</h3>
          <span className="inline-block mt-1 text-xs font-medium bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full">
            {doctor.specialization}
          </span>
        </div>
      </div>

      {/* Info */}
      <div className="flex gap-4 text-sm text-gray-500">
        <div className="flex items-center gap-1">
          <span>🎓</span>
          <span>{doctor.experience} yrs exp</span>
        </div>
        <div className="flex items-center gap-1">
          <span>📅</span>
          <span>{doctor.availability}</span>
        </div>
      </div>

      {/* Slots */}
      {doctor.availableSlots?.length > 0 && (
        <div>
          <p className="text-xs text-gray-400 mb-2 font-medium uppercase tracking-wide">Available Slots</p>
          <div className="flex flex-wrap gap-2">
            {doctor.availableSlots.map(slot => (
              <span key={slot} className="text-xs bg-green-50 text-green-700 border border-green-200 px-2 py-1 rounded-md">
                {slot}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Actions */}
      <div className="flex gap-2 pt-2 border-t border-gray-50">
        <button
          onClick={() => onBook(doctor._id)}
          className="flex-1 bg-blue-600 text-white text-sm font-medium py-2 rounded-lg hover:bg-blue-700 transition"
        >
          Book Appointment
        </button>
        <button
          onClick={() => onChat(doctor._id)}
          className="px-4 py-2 border border-blue-600 text-blue-600 text-sm font-medium rounded-lg hover:bg-blue-50 transition"
        >
          Chat
        </button>
      </div>
    </div>
  );
}
